=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time when the revision was created.

=item * C<< $msg->update_time() >> / C<< $msg->update_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time when the revision was last modified.

=item * C<< $msg->action() >> / C<< $msg->action($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::Revision::Action>)

Output only. The action which created this revision

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::Revision::State>)

Output only. Current state of the revision.

=item * C<< $msg->apply_results() >> / C<< $msg->apply_results($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::ApplyResults>)

Output only. Outputs and artifacts from applying a deployment.

=item * C<< $msg->state_detail() >> / C<< $msg->state_detail($value) >>

Type: C<String>

Output only. Additional info regarding the current state.

=item * C<< $msg->error_code() >> / C<< $msg->error_code($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::Revision::ErrorCode>)

Output only. Code describing any errors that may have occurred.

=item * C<< $msg->build() >> / C<< $msg->build($value) >>

Type: C<String>

Output only. Cloud Build instance UUID associated with this revision.

=item * C<< $msg->logs() >> / C<< $msg->logs($value) >>

Type: C<String>

Output only. Location of Revision operation logs in
`gs://{bucket}/{object}` format.

=item * C<< $msg->tf_errors() >> / C<< $msg->tf_errors($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::TerraformError>)

Output only. Errors encountered when creating or updating this deployment.
Errors are truncated to 10 entries, see `delete_results` and `error_logs`
for full details.

=item * C<< $msg->error_logs() >> / C<< $msg->error_logs($value) >>

Type: C<String>

Output only. Location of Terraform error logs in Google Cloud Storage.
Format: `gs://{bucket}/{object}`.

=item * C<< $msg->service_account() >> / C<< $msg->service_account($value) >>

Type: C<String>

Output only. User-specified Service Account (SA) to be used as credential
to manage resources. Format:
`projects/{projectID}/serviceAccounts/{serviceAccount}`

=item * C<< $msg->import_existing_resources() >> / C<< $msg->import_existing_resources($value) >>

Type: C<Bool>

Output only. By default, Infra Manager will return a failure when
Terraform encounters a 409 code (resource conflict error) during actuation.
If this flag is set to true, Infra Manager will instead
attempt to automatically import the resource into the Terraform state (for
supported resource types) and continue actuation.

Not all resource types are supported, refer to documentation.

=item * C<< $msg->worker_pool() >> / C<< $msg->worker_pool($value) >>

Type: C<String>

Output only. The user-specified Cloud Build worker pool resource in which
the Cloud Build job will execute. Format:
`projects/{project}/locations/{location}/workerPools/{workerPoolId}`.
If this field is unspecified, the default Cloud Build worker pool will be
used.

=item * C<< $msg->tf_version_constraint() >> / C<< $msg->tf_version_constraint($value) >>

Type: C<String>

Output only. The user-specified Terraform version constraint.
Example: "=1.3.10".

=item * C<< $msg->tf_version() >> / C<< $msg->tf_version($value) >>

Type: C<String>

Output only. The version of Terraform used to create the Revision.
It is in the format of "Major.Minor.Patch", for example, "1.3.10".

=item * C<< $msg->quota_validation_results() >> / C<< $msg->quota_validation_results($value) >>

Type: C<String>

Output only. Cloud Storage path containing quota validation results. This
field is set when a user sets Deployment.quota_validation field to ENABLED
or ENFORCED. Format: `gs://{bucket}/{object}`.

=item * C<< $msg->quota_validation() >> / C<< $msg->quota_validation($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::QuotaValidation>)

Optional. Input to control quota checks for resources in terraform
configuration files. There are limited resources on which quota validation
applies.

=item * C<< $msg->provider_config() >> / C<< $msg->provider_config($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::ProviderConfig>)

Output only. This field specifies the provider configurations.

=back

