=head2 Google::Cloud::Config::V1::Config::Preview

A preview represents a set of actions Infra Manager would perform
to move the resources towards the desired state as specified in the
configuration.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->terraform_blueprint() >> / C<< $msg->terraform_blueprint($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::TerraformBlueprint>)

The terraform blueprint to preview.

=item * C<< $msg->name() >> / C<< $msg->name($value) >>

Type: C<String>

Identifier. Resource name of the preview. Resource name can be user
provided or server generated ID if unspecified. Format:
`projects/{project}/locations/{location}/previews/{preview}`

=item * C<< $msg->create_time() >> / C<< $msg->create_time($value) >>

Type: C<Message> (L<Google::Protobuf::Timestamp::Timestamp>)

Output only. Time the preview was created.

=item * C<< $msg->labels() >> / C<< $msg->labels($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::Preview::LabelsEntry>)

Optional. User-defined labels for the preview.

=item * C<< $msg->state() >> / C<< $msg->state($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::Preview::State>)

Output only. Current state of the preview.

=item * C<< $msg->deployment() >> / C<< $msg->deployment($value) >>

Type: C<String>

Optional. Deployment reference. If specified, the preview will be performed
using the provided deployment's current state and use any relevant fields
from the deployment unless explicitly specified in the preview create
request.

=item * C<< $msg->preview_mode() >> / C<< $msg->preview_mode($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::Preview::PreviewMode>)

Optional. Current mode of preview.

=item * C<< $msg->service_account() >> / C<< $msg->service_account($value) >>

Type: C<String>

Required. User-specified Service Account (SA) credentials to be used when
previewing resources.
Format: `projects/{projectID}/serviceAccounts/{serviceAccount}`

=item * C<< $msg->artifacts_gcs_bucket() >> / C<< $msg->artifacts_gcs_bucket($value) >>

Type: C<String>

User-defined location of Cloud Build logs, artifacts, and
in Google Cloud Storage.
Format: `gs://{bucket}/{folder}`
A default bucket will be bootstrapped if the field is not set or empty
Default Bucket Format: `gs://<project number>-<region>-blueprint-config`
Constraints:
- The bucket needs to be in the same project as the deployment
- The path cannot be within the path of `gcs_source`
If omitted and deployment resource ref provided has artifacts_gcs_bucket
defined, that artifact bucket is used.

=item * C<< $msg->worker_pool() >> / C<< $msg->worker_pool($value) >>

Type: C<String>

The user-specified Worker Pool resource in which the Cloud Build job will
execute.
Format projects/{project}/locations/{location}/workerPools/{workerPoolId}
If this field is unspecified, the default Cloud Build worker pool will be
used. If omitted and deployment resource ref provided has worker_pool
defined, that worker pool is used.

=item * C<< $msg->error_code() >> / C<< $msg->error_code($value) >>

Type: C<Enum> (L<Google::Cloud::Config::V1::Preview::ErrorCode>)

Output only. Code describing any errors that may have occurred.

=item * C<< $msg->error_status() >> / C<< $msg->error_status($value) >>

Type: C<Message> (L<Google::Rpc::Status::Status>)

Output only. Additional information regarding the current state.

=item * C<< $msg->build() >> / C<< $msg->build($value) >>

Type: C<String>

Output only. Cloud Build instance UUID associated with this preview.

=item * C<< $msg->tf_errors() >> / C<< $msg->tf_errors($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::TerraformError>)

Output only. Summary of errors encountered during Terraform preview.
It has a size limit of 10, i.e. only top 10 errors will be summarized here.

=item * C<< $msg->error_logs() >> / C<< $msg->error_logs($value) >>

Type: C<String>

Output only. Link to tf-error.ndjson file, which contains the full list of
the errors encountered during a Terraform preview.
Format: `gs://{bucket}/{object}`.

=item * C<< $msg->preview_artifacts() >> / C<< $msg->preview_artifacts($value) >>

Type: C<Message> (L<Google::Cloud::Config::V1::Config::PreviewArtifacts>)

Output only. Artifacts from preview.

=item * C<< $msg->logs() >> / C<< $msg->logs($value) >>

Type: C<String>

Output only. Location of preview logs in `gs://{bucket}/{object}` format.

=item * C<< $msg->tf_version() >> / C<< $msg->tf_version($value) >>

Type: C<String>

Output only. The current Terraform version set on the preview.
It is in the format of "Major.Minor.Patch", for example, "1.3.10".

=item * C<< $msg->tf_version_constraint() >> / C<< $msg->tf_version_constraint($value) >>

Type: C<String>

The user-specified Terraform version constraint.
Example: "=1.3.10".

